<?php $pageTitle='Metas de ahorro'; $target=(float)$totals['target'];$saved=(float)$totals['saved'];$overall=$target>0?min(100,$saved/$target*100):0; ?><section class="page-head"><div><p class="eyebrow">Ahorro</p><h1>Metas de ahorro</h1><p class="muted">Convierte pequeños aportes en objetivos reales.</p></div><button class="btn primary" onclick="document.getElementById('goal-form').scrollIntoView({behavior:'smooth'})">+ Nueva meta</button></section><div class="stats-grid"><div class="stat-card"><span>Ahorro total</span><strong>$<?=number_format($saved,0,',','.')?></strong><small>COP</small></div><div class="stat-card"><span>Objetivo general</span><strong>$<?=number_format($target,0,',','.')?></strong><small>COP</small></div><div class="stat-card"><span>Progreso general</span><strong><?=number_format($overall,0)?>%</strong><small>de tus metas</small></div></div><div class="panel"><div class="panel-title"><h2>Crear una meta</h2></div><form id="goal-form" class="form-grid" method="post" action="index.php?url=goal/save"><input type="hidden" name="csrf" value="<?=$csrf?>"><label>Nombre de la meta<input name="name" placeholder="Ej. Computador nuevo" required></label><label>Monto objetivo<input type="number" name="target_amount" min="1" required></label><label>Monto inicial<input type="number" name="initial_amount" min="0" value="0"></label><label>Fecha límite (opcional)<input type="date" name="deadline"></label><button class="btn primary">Crear meta</button></form></div><div class="goal-grid"><?php foreach($goals as $g): $p=$g['target_amount']>0?min(100,$g['saved']/$g['target_amount']*100):0;$remaining=max(0,$g['target_amount']-$g['saved']);$days=$g['deadline']?floor((strtotime($g['deadline'])-strtotime(date('Y-m-d')))/86400):null;$tip=$p>=100?'¡Meta alcanzada! Cada paso cuenta.':($days!==null&&$days<=30?'Si sigues así podrás alcanzar tu meta en menos de un mes.':'Pasos pequeños logran grandes triunfos.'); ?><article class="panel goal-card"><div class="goal-top"><div><span class="goal-icon">◎</span><h2><?=htmlspecialchars($g['name'])?></h2></div><div class="goal-actions"><button class="icon-btn" onclick="toggleModal('goal-<?=$g['id']?>')">✎</button><form method="post" action="index.php?url=goal/delete" onsubmit="return confirm('¿Eliminar meta y sus abonos?')"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$g['id']?>"><button class="icon-btn danger">×</button></form></div></div><div class="goal-numbers"><strong>$<?=number_format($g['saved'],0,',','.')?></strong><span>de $<?=number_format($g['target_amount'],0,',','.')?></span></div><div class="progress"><i style="width:<?=$p?>%"></i></div><div class="goal-meta"><span><?=number_format($p,0)?>% completado</span><span><?=$g['deadline']?'Límite: '.date('d/m/Y',strtotime($g['deadline'])):'Sin fecha límite'?></span></div><?php if($days!==null && $days>=0 && $days<=7 && $p<100): ?><div class="warning-note">⏰ Tu fecha límite se acerca: quedan <?=$days?> día<?=$days==1?'':'s'?>.</div><?php endif; ?><div class="tip">💡 <?=htmlspecialchars($tip)?></div><form class="inline-form" method="post" action="index.php?url=goal/contribution"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="goal_id" value="<?=$g['id']?>"><input type="number" name="amount" min="1" placeholder="Abono" required><input type="date" name="date" value="<?=date('Y-m-d')?>" required><input name="note" placeholder="Nota opcional"><button class="btn primary">Abonar</button></form><details><summary>Ver movimientos de esta meta</summary><div class="mini-table"><?php $cs=Goal::contributions((int)$g['id'],Auth::user()['id']); foreach($cs as $c): ?><div><span><?=date('d/m/Y',strtotime($c['date']))?> · <?=htmlspecialchars($c['note']??'Abono')?></span><strong>$<?=number_format($c['amount'],0,',','.')?></strong><a class="text-edit" href="index.php?url=goal/editContribution&id=<?=$c['id']?>">Editar</a><form method="post" action="index.php?url=goal/deleteContribution"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="text-danger">Eliminar</button></form></div><?php endforeach; if(!$cs): ?><p class="muted">No hay abonos todavía.</p><?php endif; ?></div></details><div id="goal-<?=$g['id']?>" class="modal"><div class="modal-box"><button onclick="toggleModal('goal-<?=$g['id']?>')" class="close">×</button><h2>Editar meta</h2><form class="form-grid" method="post" action="index.php?url=goal/edit"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$g['id']?>"><label>Nombre<input name="name" value="<?=htmlspecialchars($g['name'])?>"></label><label>Objetivo<input type="number" name="target_amount" value="<?=$g['target_amount']?>"></label><p class="muted">El monto inicial se conserva; puedes modificar el objetivo y la fecha límite.</p><label>Límite<input type="date" name="deadline" value="<?=$g['deadline']?>"></label><button class="btn primary">Guardar</button></form></div></div></article><?php endforeach; ?></div>